import java.util.*;

public class Main {
    static long[] pattern = new long[18];
    static int min_moves = Integer.MAX_VALUE;

    static void recurse(int current_moves, long remaining_value, int position) {
        if (current_moves > min_moves)
            return;
        if (remaining_value == 0) {
            min_moves = Math.min(min_moves, current_moves);
            return;
        }
        int needed_times = (int) (remaining_value / pattern[position]);
        recurse(current_moves + position * needed_times + 1, remaining_value - needed_times * pattern[position], position - 1);
        recurse(current_moves + needed_times * position, needed_times * pattern[position] - remaining_value, position - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long input_value = sc.nextLong();
        pattern[1] = 1;
        for (int i = 2; i < 18; i++) {
            pattern[i] = pattern[i - 1] * 10 + 1;
        }
        long temp = input_value;
        min_moves = 1000000000;
        while (temp > 0) {
            for (int i = 1; i < 18; i++) {
                if (pattern[i] > temp) {
                    min_moves += (i - 1);
                    temp -= pattern[i - 1];
                    break;
                }
            }
        }
        recurse(0, input_value, 16);
        System.out.println(min_moves);
        sc.close();
    }
}
